//! Hand-derived ASP output goldens; never generated by the production evaluator.
use lc631_solvers::asp::*;
use lc631_solvers::protocol::clingo::ClingoTerminalStatus;
use lc631_substrate::context_identity::{ContextRevision, SourceRevision};
use lc631_substrate::Digest32;

fn program(models: usize, steps: u64) -> AspProgram {
    let a = AtomId::new(0);
    let b = AtomId::new(1);
    AspProgram::checked(
        AspBinding::declared(
            ContextRevision::original(SourceRevision::of("two defaults")),
            Digest32::from_bytes([2; 32]),
            Digest32::from_bytes([3; 32]),
        ),
        AspSemantics::StableModelsClosedWorld,
        vec![a, b],
        vec![
            GroundRule::new(Some(a), vec![], vec![b]),
            GroundRule::new(Some(b), vec![], vec![a]),
        ],
        vec![
            AtomCost { atom: a, weight: 3 },
            AtomCost { atom: b, weight: 3 },
        ],
        AspLimits::checked(16, 1024, 16384, models, steps, 65536).unwrap(),
    )
    .unwrap()
}

#[test]
fn tlcx12_unknown_retains_rechecked_reported_model_without_cautious_or_optimum() {
    let p = program(256, 10000);
    let result = p.reconstruct(b"Answer: 1\na1\nUNKNOWN\n").unwrap();
    assert_eq!(
        result.reported_status(),
        Some(ClingoTerminalStatus::Unknown)
    );
    assert_eq!(result.completeness(), AspCompleteness::SolverUnknown);
    assert_eq!(result.model_atoms(0), Some(vec![AtomId::new(1)]));
    assert_eq!(result.models()[0].reported_answer(), Some(1));
    assert_eq!(result.models()[0].cost(), 3);
    assert_eq!(result.minimum_cost(), None);
    assert!(result.optimal_model_indices().is_empty());
    assert_eq!(
        result
            .consequence(AtomId::new(1), ConsequenceMode::Cautious)
            .unwrap(),
        Consequence::Unknown
    );
}

#[test]
fn tlcx12_cutoff_retains_reported_order_not_unreported_local_models() {
    let p = program(1, 10000);
    let result = p
        .reconstruct(b"Answer: 1\na1\nAnswer: 2\na0\nSATISFIABLE\n")
        .unwrap();
    assert_eq!(result.completeness(), AspCompleteness::ModelLimit);
    assert_eq!(
        result.reported_status(),
        Some(ClingoTerminalStatus::Satisfiable)
    );
    assert_eq!(result.models().len(), 1);
    assert_eq!(result.model_atoms(0), Some(vec![AtomId::new(1)]));
    assert_eq!(result.models()[0].reported_answer(), Some(1));
    assert_eq!(result.minimum_cost(), None);
}

#[test]
fn tlcx12_unknown_and_step_cutoff_never_bypass_model_syntax_or_duplicate_checks() {
    let p = program(256, 1);
    assert_eq!(
        p.reconstruct(b"Answer: 1\na0 a0\nUNKNOWN\n").unwrap_err(),
        AspError::DuplicateModelAtom
    );
    assert_eq!(
        p.reconstruct(b"Answer: 1\na99\nSATISFIABLE\n").unwrap_err(),
        AspError::UndeclaredAtom
    );
    assert_eq!(
        p.reconstruct(b"Answer: 1\na0\nAnswer: 2\na0\nUNKNOWN\n")
            .unwrap_err(),
        AspError::DuplicateModel
    );
    let result = p.reconstruct(b"Answer: 1\na1\nUNKNOWN\n").unwrap();
    assert_eq!(
        result.reported_status(),
        Some(ClingoTerminalStatus::Unknown)
    );
    assert_eq!(result.completeness(), AspCompleteness::StepLimit);
    assert!(result.models().is_empty());
    assert!(result.steps() <= 1);
}

#[test]
fn tlcx12_unknown_with_invalid_stable_model_is_rejected_when_recheck_completes() {
    assert_eq!(
        program(256, 10000)
            .reconstruct(b"Answer: 1\na0 a1\nUNKNOWN\n")
            .unwrap_err(),
        AspError::InvalidStableModel
    );
}

#[test]
fn tlcx12_complete_reconstruction_preserves_cost_ties_and_all_model_quantification() {
    let result = program(256, 10000)
        .reconstruct(b"Answer: 1\na1\nAnswer: 2\na0\nSATISFIABLE\n")
        .unwrap();
    assert_eq!(result.completeness(), AspCompleteness::Exhaustive);
    assert_eq!(result.minimum_cost(), Some(3));
    assert_eq!(result.optimal_model_indices(), vec![0, 1]);
    assert_eq!(result.models()[1].reported_answer(), Some(2));
    assert_eq!(
        result
            .consequence(AtomId::new(0), ConsequenceMode::Brave)
            .unwrap(),
        Consequence::Holds
    );
    assert_eq!(
        result
            .consequence(AtomId::new(0), ConsequenceMode::Cautious)
            .unwrap(),
        Consequence::DoesNotHold
    );
    assert!(!result.clingo_native_optimization());
}
